var a=182;var i=[{id:`cooking-182-01`,theoryId:182,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`In a common autolyse for wheat dough, which ingredients are combined first?`,ua:`Які інгредієнти спершу змішують для типового автолізу пшеничного тіста?`},explanation:{en:`A rest after combining flour and water encourages hydration and easier dough development.`,ua:`Відпочинок після змішування борошна з водою покращує гідратацію та полегшує розвиток тіста.`},options:[{id:`a`,text:{en:`Flour and water`,ua:`Борошно й воду`}},{id:`b`,text:{en:`Yeast and hot oil`,ua:`Дріжджі та гарячу олію`}},{id:`c`,text:{en:`Sugar and melted chocolate`,ua:`Цукор і розтоплений шоколад`}}],answer:{optionIds:[`a`]}},{id:`cooking-182-02`,theoryId:182,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Autolyse is the same thing as baking bread at a low temperature.`,ua:`Автоліз — це те саме, що випікання хліба за низької температури.`},explanation:{en:`It is a dough-rest step, generally before full mixing.`,ua:`Це етап відпочинку тіста, зазвичай до повного замішування.`},answer:{value:!1}},{id:`cooking-182-03`,theoryId:182,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match dough rests to their purposes.`,ua:`Поєднайте етапи відпочинку тіста з їхніми цілями.`},explanation:{en:`Although all are rests, the mechanisms and goals differ.`,ua:`Хоча всі три — періоди відпочинку, механізми та цілі різні.`},leftItems:[{id:`l1`,text:{en:`Flour-water autolyse`,ua:`Автоліз борошна з водою`}},{id:`l2`,text:{en:`Bench rest after preshaping`,ua:`Відпочинок після попереднього формування`}},{id:`l3`,text:{en:`Final proof`,ua:`Остаточне вистоювання`}}],rightItems:[{id:`r2`,text:{en:`Relax tension for final shaping`,ua:`Послабити натяг перед остаточним формуванням`}},{id:`r3`,text:{en:`Allow shaped dough to expand`,ua:`Дати сформованому тісту збільшитися в об’ємі`}},{id:`r1`,text:{en:`Improve hydration and extensibility`,ua:`Покращити гідратацію та розтяжність`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-182-04`,theoryId:182,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A stiff dough tears immediately during shaping. Which planned change could help?`,ua:`Туге тісто одразу рветься під час формування. Яка зміна може допомогти?`},explanation:{en:`Adequate hydration and rest can help dough become more extensible.`,ua:`Достатня гідратація та відпочинок можуть покращити розтяжність тіста.`},options:[{id:`a`,text:{en:`Introduce appropriate hydration and a rest before further working`,ua:`Забезпечити належну гідратацію та відпочинок перед подальшою обробкою`}},{id:`b`,text:{en:`Bake it before shaping`,ua:`Випекти ще до формування`}},{id:`c`,text:{en:`Add unlimited dry flour`,ua:`Додавати необмежену кількість сухого борошна`}}],answer:{optionIds:[`a`]}},{id:`cooking-182-05`,theoryId:182,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Order a simple flour-water autolyse workflow.`,ua:`Упорядкуйте простий процес автолізу борошна з водою.`},explanation:{en:`Autolyse rests hydrated flour before full dough development.`,ua:`Автоліз передбачає відпочинок зволоженого борошна до повного замішування.`},steps:[{id:`s2`,text:{en:`Mix until the flour is hydrated`,ua:`Змішати до зволоження борошна`}},{id:`s4`,text:{en:`Add remaining ingredients and continue mixing`,ua:`Додати решту інгредієнтів та продовжити замішування`}},{id:`s1`,text:{en:`Measure flour and water`,ua:`Відміряти борошно та воду`}},{id:`s3`,text:{en:`Cover and let the mixture rest`,ua:`Накрити та залишити суміш відпочити`}}],answer:{order:[`s1`,`s2`,`s3`,`s4`]}}];var n={theoryId:182,exercises:i};export{n as default,i as exercises,a as theoryId};